export const DEFAULT_BKASH_QR_IMAGE = "data:image/png;base64,";

export function isDefaultOrMockQr(qr: string | null | undefined): boolean {
  if (!qr || qr.trim() === "") return true;
  if (qr === "/images/bkash-qr.png") return true;
  if (qr.includes("data:image/svg+xml") || qr.includes("<svg") || qr.includes("%3Csvg")) return true;
  return false;
}

export function getEffectiveBkashQr(qr: string | null | undefined): string {
  if (!qr || isDefaultOrMockQr(qr)) {
    return DEFAULT_BKASH_QR_IMAGE;
  }
  return qr;
}
